public bool IsValid(string s) {
    if (s.Length % 2 == 1) return false;            // someone is left without a pair
    var pairs = new Dictionary<char, char> { [')'] = '(', [']'] = '[', ['}'] = '{' };
    var stack = new Stack<char>();
    foreach (char c in s) {
        if (!pairs.TryGetValue(c, out char open)) stack.Push(c);       // opening
        else if (stack.Count == 0 || stack.Pop() != open) return false; // closing
    }
    return stack.Count == 0;                         // was everything closed?
}

