public class MinStack2 {
    readonly Stack<int> vals = new Stack<int>();
    readonly Stack<int> mins = new Stack<int>();       // “records” only

    public void Push(int x) {
        vals.Push(x);
        if (mins.Count == 0 || x <= mins.Peek()) mins.Push(x);   // <=, not <
    }
    public void Pop() {
        if (vals.Pop() == mins.Peek()) mins.Pop();      // a record left — drop it too
    }
    public int Top() => vals.Peek();
    public int GetMin() => mins.Peek();
}

