public interface ICommand { void Do(); void Undo(); }

public sealed class History {
    readonly Stack<ICommand> undo = new Stack<ICommand>();
    readonly Stack<ICommand> redo = new Stack<ICommand>();

    public void Run(ICommand cmd) {
        cmd.Do();
        undo.Push(cmd);
        redo.Clear();                              // history has branched
    }
    public void Undo() {
        if (!undo.TryPop(out var cmd)) return;     // TryPop: no exception when empty
        cmd.Undo();
        redo.Push(cmd);
    }
    public void Redo() {
        if (!redo.TryPop(out var cmd)) return;
        cmd.Do();
        undo.Push(cmd);
    }
}
